
// Zoho Desk Live Dashboard - Backend Server
const express = require('express');
const app = express();
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS, PUT, DELETE');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization, X-Requested-With');
  if (req.method === 'OPTIONS') return res.sendStatus(204);
  next();
});
app.use(express.json({ limit: '1mb' }));
const DC = process.env.ZOHO_DC || 'com';
const ORG_ID = process.env.ZOHO_ORG_ID;
const CLIENT_ID = process.env.ZOHO_CLIENT_ID;
const CLIENT_SECRET = process.env.ZOHO_CLIENT_SECRET;
const REFRESH_TOKEN = process.env.ZOHO_REFRESH_TOKEN;
const PORT = process.env.PORT || 3001;
const DESK_BASE = `https://desk.zoho.${DC}/api/v1`;
const ACCOUNTS_BASE = `https://accounts.zoho.${DC}/oauth/v2/token`;
let tokenCache = { accessToken: null, expiresAt: 0 };
async function refreshAccessToken() {
  const params = new URLSearchParams({ refresh_token: REFRESH_TOKEN, client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'refresh_token' });
  const res = await fetch(`${ACCOUNTS_BASE}?${params.toString()}`, { method: 'POST' });
  const data = await res.json();
  if (!res.ok || !data.access_token) throw new Error('Token refresh failed: ' + JSON.stringify(data));
  tokenCache = { accessToken: data.access_token, expiresAt: Date.now() + (data.expires_in * 1000) - (5 * 60 * 1000) };
  return tokenCache.accessToken;
}
async function getValidToken() {
  if (!tokenCache.accessToken || Date.now() >= tokenCache.expiresAt) return await refreshAccessToken();
  return tokenCache.accessToken;
}
async function zoho(path, orgId = ORG_ID) {
  let token = await getValidToken();
  let res = await fetch(DESK_BASE + path, { headers: { Authorization: 'Zoho-oauthtoken ' + token, orgId } });
  if (res.status === 401) {
    token = await refreshAccessToken();
    res = await fetch(DESK_BASE + path, { headers: { Authorization: 'Zoho-oauthtoken ' + token, orgId } });
  }
  return res;
}
let sseClients = [];
function broadcast(event) {
  const payload = `data: ${JSON.stringify(event)}\n\n`;
  sseClients = sseClients.filter(c => !c.destroyed);
  sseClients.forEach(c => c.write(payload));
}
let lastWebhookAt = null; let webhookLog = [];
app.get('/api/health', (req, res) => res.json({ ok: true, dc: DC, orgId: ORG_ID ? 'set' : 'missing', sseClients: sseClients.length, lastWebhookAt }));
const INCLUDE_ALL = 'assignee,departments,team,contacts';
async function tryFetchTickets(qs, orgId) {
  const r = await zoho(`/tickets?${qs.toString()}`, orgId);
  const txt = await r.text(); let j; try { j = JSON.parse(txt); } catch { return { arr: [], err: 'parse' }; }
  if (j.error || j.errorCode) return { arr: [], err: JSON.stringify(j).slice(0,400) };
  return { arr: Array.isArray(j) ? j : (j.data || j.tickets || []), err: null };
}
async function fetchTicketsPage(teamId, deptId, from, limit, statusFilter, orgId) {
  const buildQs = (withInclude) => {
    const q = new URLSearchParams({ limit: String(limit), from: String(from), sortBy: '-createdTime' });
    if (withInclude) q.set('include', INCLUDE_ALL);
    if (statusFilter) q.set('status', statusFilter);
    return q;
  };
  const filterId = teamId || deptId;
  if (filterId) {
    const candidates = [];
    const q1 = buildQs(true); q1.set('teamIds', filterId); candidates.push({qs:q1, via:'teamIds'});
    const q2 = buildQs(true); q2.set('departmentIds', filterId); candidates.push({qs:q2, via:'departmentIds'});
    const q3 = buildQs(true); q3.set('departmentId', filterId); candidates.push({qs:q3, via:'departmentId'});
    const q1b = buildQs(false); q1b.set('teamIds', filterId); candidates.push({qs:q1b, via:'teamIds (no include)'});
    const q2b = buildQs(false); q2b.set('departmentIds', filterId); candidates.push({qs:q2b, via:'departmentIds (no include)'});
    for (const c of candidates) {
      const res = await tryFetchTickets(c.qs, orgId);
      if (res.err) { console.log('[Tickets] try', c.via, 'err', res.err); continue; }
      if (res.arr.length>0) return { arr: res.arr, via: c.via };
    }
    try {
      const tr = await zoho(`/teams/${filterId}`, orgId);
      const tj = await tr.json();
      const tObj = tj.data || tj;
      const deptIdOfTeam = tObj.departmentId || tObj.department?.id || '';
      if (deptIdOfTeam && String(deptIdOfTeam)!==String(filterId)) {
        const qD = buildQs(true); qD.set('departmentIds', String(deptIdOfTeam));
        const rr = await tryFetchTickets(qD, orgId);
        if (!rr.err && rr.arr.length>0) return { arr: rr.arr, via: 'team->dept fallback dept '+deptIdOfTeam };
      }
    } catch(e){ console.log('[Tickets] team->dept fallback failed', e.message); }
    return { arr: [], via: 'none' };
  }
  for (const withInc of [true, false]) {
    const qAll = buildQs(withInc);
    const res = await tryFetchTickets(qAll, orgId);
    if (!res.err) return { arr: res.arr, via: withInc ? 'all' : 'all (no include)' };
    console.log('[Tickets] unfiltered err', res.err);
  }
  return { arr: [], via: 'none - Zoho error' };
}
function enrichTickets(merged, deptMap, teamMap) {
  merged.forEach(t=>{
    const did=String(t.departmentId||t.department?.id||'');
    if(did && deptMap[did]) t._deptName=deptMap[did]; else if(t.department?.name) t._deptName=t.department.name;
    if(t.team && typeof t.team==='object' && t.team.name) t._teamName=t.team.name;
    else if(t.teamId && teamMap[String(t.teamId)]) t._teamName=teamMap[String(t.teamId)];
    if(t.assignee && typeof t.assignee==='object'){ const fn=(t.assignee.firstName||'').trim(); const ln=(t.assignee.lastName||'').trim(); const nm=(fn+' '+ln).trim() || t.assignee.name || t.assignee.email || ''; if(nm) t._assigneeName=nm; }
    const c = t.contact || (Array.isArray(t.contacts)?t.contacts[0]:null) || null;
    if(c && typeof c==='object'){ const fn=(c.firstName||'').trim(); const ln=(c.lastName||'').trim(); const nm=(fn+' '+ln).trim() || c.name || ''; if(nm) t._contactName=nm; if(c.email) t._contactEmail=c.email; }
    if(t.contactName && !t._contactName) t._contactName=t.contactName;
    if(t.contactEmail && !t._contactEmail) t._contactEmail=t.contactEmail;
  });
  return merged;
}
async function loadMaps(orgId) {
  let deptMap={}, teamMap={}, deptIds=[];
  try { for(let from=1; from<=2000; from+=200){ const dr = await zoho(`/departments?limit=200&from=${from}`, orgId); const dj = await dr.json(); const dlist = Array.isArray(dj)?dj:(dj.data||dj.departments||[]); if(!dlist.length) break; dlist.forEach(d=>{ const id=d.id||d.departmentId; if(id){ deptIds.push(String(id)); deptMap[String(id)]=d.name||d.departmentName||String(id); } }); if(dlist.length<200) break; } } catch(e){ console.log('[loadMaps] depts err', e.message); }
  const addTeam = (t)=>{ const id=t.id||t.teamId; if(id && !teamMap[String(id)]) teamMap[String(id)]=t.name||t.teamName||String(id); };
  try { for(let from=1; from<=2000; from+=200){ const tr = await zoho(`/teams?limit=200&from=${from}`, orgId); const tj = await tr.json(); const tlist = Array.isArray(tj)?tj:(tj.data||tj.teams||[]); if(!tlist.length) break; tlist.forEach(addTeam); if(tlist.length<200) break; } } catch(e){ console.log('[loadMaps] teams err', e.message); }
  for(const did of deptIds){ try { const tr2 = await zoho(`/teams?limit=200&from=1&departmentId=${did}`, orgId); const tj2 = await tr2.json(); const l2 = Array.isArray(tj2)?tj2:(tj2.data||tj2.teams||[]); l2.forEach(addTeam); } catch(e){} try { const tr3 = await zoho(`/departments/${did}/teams?limit=200&from=1`, orgId); const tj3 = await tr3.json(); const l3 = Array.isArray(tj3)?tj3:(tj3.data||tj3.teams||[]); l3.forEach(addTeam); } catch(e){} }
  return { deptMap, teamMap, deptIds };
}
app.get('/api/diag', async (req, res) => {
  try {
    const out = {};
    for (const withInc of [true, false]) {
      const qs = new URLSearchParams({ limit: '5', from: '1', sortBy: '-createdTime' });
      if (withInc) qs.set('include', INCLUDE_ALL);
      const r = await zoho(`/tickets?${qs.toString()}`, req.query.orgId);
      const txt = await r.text(); let j; try { j = JSON.parse(txt); } catch { j = { parseError: txt.slice(0,300) }; }
      const arr = Array.isArray(j) ? j : (j.data || j.tickets || []);
      out[withInc ? 'withInclude' : 'withoutInclude'] = { count: arr.length, error: j.error || j.errorCode || null, sample: arr.slice(0,1).map(t=>({ticketNumber:t.ticketNumber, createdTime:t.createdTime, teamId:t.teamId, departmentId:t.departmentId})) };
    }
    try { const tr = await zoho('/teams?limit=200&from=1', req.query.orgId); const tj = await tr.json(); const tl = Array.isArray(tj)?tj:(tj.data||tj.teams||[]); out.teams = { count: tl.length, sample: tl.slice(0,3).map(t=>({id:String(t.id||t.teamId), name:t.name||t.teamName})) }; } catch(e){ out.teams={error:e.message}; }
    try { const dr = await zoho('/departments?limit=200&from=1', req.query.orgId); const dj = await dr.json(); const dl = Array.isArray(dj)?dj:(dj.data||dj.departments||[]); out.departments = { count: dl.length, sample: dl.slice(0,3).map(d=>({id:String(d.id||d.departmentId), name:d.name||d.departmentName})) }; } catch(e){ out.departments={error:e.message}; }
    return res.json(out);
  } catch(e){ res.status(500).json({ error: e.message }); }
});
app.get('/api/tickets', async (req, res) => {
  try {
    const limit = Math.min(parseInt(req.query.limit || '100'), 100);
    const from = parseInt(req.query.from || '1');
    const teamId = req.query.teamId || req.query.teamIds || '';
    const deptId = req.query.departmentId || req.query.departmentIds || '';
    const statusFilter = req.query.status;
    const { deptMap, teamMap, deptIds } = await loadMaps(req.query.orgId);
    const filterId = teamId || deptId;
    let merged = []; let filterUsed='none';
    if (filterId) {
      const filterIds = String(filterId).split(',').map(s=>s.trim()).filter(Boolean);
      if (filterIds.length > 1) {
        // MULTI-TEAM: fetch each team separately and merge (Zoho only filters 1 team per call)
        const perTeam = [];
        for (const fid of filterIds) {
          const r = await fetchTicketsPage(fid, fid, from, limit, statusFilter, req.query.orgId);
          perTeam.push(...r.arr);
          filterUsed = (filterUsed==='none' ? '' : filterUsed+', ') + fid + ':' + r.via;
        }
        merged = perTeam;
        if (merged.length===0) {
          const qAll = new URLSearchParams({ limit: String(limit), from: String(from), sortBy: '-createdTime', include: INCLUDE_ALL });
          const rr = await zoho(`/tickets?${qAll.toString()}`, req.query.orgId);
          const txt = await rr.text(); let jj; try { jj = JSON.parse(txt); } catch { jj=[]; }
          const all = Array.isArray(jj)?jj:(jj.data||jj.tickets||[]);
          merged = all.filter(t => filterIds.includes(String(t.teamId||t.team?.id||'')) || filterIds.includes(String(t.departmentId||t.department?.id||'')));
          if (merged.length>0) filterUsed='client-side multi teamId/departmentId';
        }
      } else {
        const r = await fetchTicketsPage(teamId, deptId, from, limit, statusFilter, req.query.orgId);
        merged = r.arr; filterUsed = r.via;
        if (merged.length===0) {
          const qAll = new URLSearchParams({ limit: String(limit), from: String(from), sortBy: '-createdTime', include: INCLUDE_ALL });
          const rr = await zoho(`/tickets?${qAll.toString()}`, req.query.orgId);
          const txt = await rr.text(); let jj; try { jj = JSON.parse(txt); } catch { jj=[]; }
          const all = Array.isArray(jj)?jj:(jj.data||jj.tickets||[]);
          merged = all.filter(t => String(t.teamId||t.team?.id||'')===String(filterId) || String(t.departmentId||t.department?.id||'')===String(filterId));
          if (merged.length>0) filterUsed='client-side teamId/departmentId';
        }
      }
    } else {
      const qsAll = new URLSearchParams({ limit: String(limit), from: String(from), sortBy: '-createdTime', include: INCLUDE_ALL });
      if (statusFilter) qsAll.set('status', statusFilter);
      const rAll = await zoho(`/tickets?${qsAll.toString()}`, req.query.orgId);
      const txtAll = await rAll.text(); let jAll; try { jAll=JSON.parse(txtAll); } catch { jAll=[]; }
      const unfiltered = Array.isArray(jAll)?jAll:(jAll.data||jAll.tickets||[]);
      const jobs = deptIds.map(did => {
        const qs = new URLSearchParams({ limit: String(limit), from: String(from), sortBy: '-createdTime', include: INCLUDE_ALL });
        qs.set('departmentId', did);
        if (statusFilter) qs.set('status', statusFilter);
        return (async()=>{ const rr=await zoho(`/tickets?${qs.toString()}`, req.query.orgId); const txt=await rr.text(); try{ const jj=JSON.parse(txt); return Array.isArray(jj)?jj:(jj.data||jj.tickets||[]); }catch{ return []; } })();
      });
      const results = await Promise.all(jobs);
      merged = [...unfiltered, ...results.flat()].filter(Boolean); filterUsed='all teams (unfiltered + per-dept)';
    }
    enrichTickets(merged, deptMap, teamMap);
    const map = new Map(); merged.forEach(t=>map.set(t.ticketNumber||t.id, t));
    const deduped = [...map.values()].sort((a,b)=> new Date(b.createdTime||0)-new Date(a.createdTime||0));
    return res.json({ data: deduped, _filterId: filterId||null, _filterUsed: filterUsed, _totalMerged: deduped.length, _deptMap: deptMap, _teamMap: teamMap });
  } catch(e){ res.status(500).json({ error: e.message }); }
});
function closedDateBackend(t){ const c=t.closedTime || t.closed_time || ((t.status==='Closed'||t.status==='Resolved') ? (t.modifiedTime||t.updatedTime) : null); return c||null; }
function matchesRangeBackend(t, fromDate, toDate){
  if(!fromDate && !toDate) return true;
  const fmtIST=(d)=>{ try{ return new Date(d).toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'}); }catch{ return ''; } };
  const c=fmtIST(t.createdTime); if(!c) return false;
  const st=(t.status==='Resolved'?'Closed':t.status);
  const cdRaw=closedDateBackend(t); const cd=cdRaw?fmtIST(cdRaw):'';
  if(fromDate && toDate){
    if(c>toDate) return false;
    if(st!=='Closed') return true;
    if(c>=fromDate && c<=toDate) return true;
    if(cd && cd>=fromDate && cd<=toDate) return true;
    if(cd && cd>toDate) return true;
    if(!cd){ const md=fmtIST(t.modifiedTime); if(md && md>=fromDate && md<=toDate) return true; return false; }
    return false;
  }
  if(fromDate && !toDate){
    if(st!=='Closed') return true;
    if(c>=fromDate) return true;
    if(cd && cd>=fromDate) return true;
    return false;
  }
  return c<=toDate;
}
app.get('/api/tickets/range', async (req, res) => {
  try {
    const fromDate = req.query.fromDate || ''; const toDate = req.query.toDate || '';
    const teamId = req.query.teamId || ''; const deptId = req.query.departmentId || '';
    const maxPages = Math.min(parseInt(req.query.maxPages||'150'), 200);
    const statusFilter = req.query.status;
    const { deptMap, teamMap } = await loadMaps(req.query.orgId);
    const fmtIST = (d)=>{ try{ return new Date(d).toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'}); }catch{ return ''; } };
    const map=new Map(); let pagesFetched=0; let pagesPastFrom=0; let filterUsed='teamIds';
    const rangeTeamIds = String(teamId||'').split(',').map(s=>s.trim()).filter(Boolean);
    const rangeTargets = rangeTeamIds.length>1 ? rangeTeamIds : [teamId||''];
    for(const targetTeamId of rangeTargets){
      for(let page=1; page<=maxPages; page++){
        const from=(page-1)*100+1;
        const r = await fetchTicketsPage(targetTeamId, targetTeamId||deptId, from, 100, statusFilter, req.query.orgId);
        filterUsed = rangeTeamIds.length>1 ? ('multi:'+rangeTeamIds.length+' teams, last '+r.via) : r.via;
        const arr=r.arr; pagesFetched=Math.max(pagesFetched, page);
        if(arr.length===0) break;
        let pageCarry=0;
        for(const t of arr){ if(matchesRangeBackend(t, fromDate, toDate)){ map.set(t.ticketNumber||t.id, t); const d=fmtIST(t.createdTime); if(fromDate && d<fromDate) pageCarry++; } }
        const oldest=fmtIST(arr[arr.length-1].createdTime);
        if(arr.length<100) break;
        if(fromDate){ if(pageCarry>0) pagesPastFrom=0; else if(oldest < fromDate){ pagesPastFrom++; if(pagesPastFrom>=3) break; } else pagesPastFrom=0; }
        if(page%10===0) await new Promise(res=>setTimeout(res,100));
      }
    }
    let merged=[...map.values()];
    enrichTickets(merged, deptMap, teamMap);
    merged.sort((a,b)=> new Date(b.createdTime||0)-new Date(a.createdTime||0));
    return res.json({ data: merged, _filterUsed: filterUsed, _pagesFetched: pagesFetched, _totalMerged: merged.length, _fromDate: fromDate, _toDate: toDate });
  } catch(e){ res.status(500).json({ error: e.message }); }
});
app.get('/api/agents', async (req, res) => {
  try {
    let all = [];
    for (let from=1; from<=2000; from+=200) {
      const qs = new URLSearchParams({ limit: '200', from: String(from), include: 'profile,role' }).toString();
      const r = await zoho(`/agents?${qs}`, req.query.orgId);
      const txt = await r.text();
      let j; try { j = JSON.parse(txt); } catch { break; }
      if (j.error || j.errorCode) break;
      const arr = Array.isArray(j) ? j : (j.data || j.agents || []);
      if (arr.length===0) break;
      all.push(...arr);
      if (arr.length < 200) break;
    }
    return res.json({ data: all, _total: all.length });
  } catch(e){ res.status(500).json({ error: e.message }); }
});
app.get('/api/tickets/:id/activities', async (req, res) => {
  try {
    const tid = req.params.id;
    const tries = [`/tickets/${tid}/activities?limit=200&from=1`, `/tickets/${tid}/history?limit=200&from=1`, `/tickets/${tid}/activities`];
    for(const path of tries){
      try { const r = await zoho(path, req.query.orgId); const txt = await r.text(); let j; try { j = JSON.parse(txt); } catch { continue; } if(j.error || j.errorCode) continue; const arr = Array.isArray(j) ? j : (j.data || j.activities || j.history || []); return res.json({ data: arr, _via: path }); } catch(e){}
    }
    return res.json({ data: [], _via: 'none' });
  } catch(e){ res.status(500).json({ error: e.message }); }
});
