app.get('/api/teams', async (req, res) => {
  try {
    let all = []; const seen = new Set();
    const pushAll = (arr)=>{ for(const t of arr){ const id=String(t.id||t.teamId||''); if(id && !seen.has(id)){ seen.add(id); all.push(t); } } };
    for (let from=1; from<=2000; from+=200) {
      const r = await zoho(`/teams?limit=200&from=${from}`, req.query.orgId);
      const txt = await r.text();
      let j; try { j = JSON.parse(txt); } catch { break; }
      if (j.error || j.errorCode) break;
      const arr = Array.isArray(j) ? j : (j.data || j.teams || []);
      if (arr.length===0) break;
      pushAll(arr);
      if (arr.length < 200) break;
    }
    try { const { deptIds } = await loadMaps(req.query.orgId); for(const did of deptIds){ try { const r2 = await zoho(`/teams?limit=200&from=1&departmentId=${did}`, req.query.orgId); const t2 = await r2.text(); const j2 = JSON.parse(t2); const a2 = Array.isArray(j2)?j2:(j2.data||j2.teams||[]); pushAll(a2); } catch(e){} try { const r3 = await zoho(`/departments/${did}/teams?limit=200&from=1`, req.query.orgId); const t3 = await r3.text(); const j3 = JSON.parse(t3); const a3 = Array.isArray(j3)?j3:(j3.data||j3.teams||[]); pushAll(a3); } catch(e){} } } catch(e){ console.log('[api/teams] per-dept err', e.message); }
    return res.json({ data: all, _total: all.length });
  } catch(e){ res.status(500).json({ error: e.message }); }
});
